  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'Mathematics', 'A soldier runs 1.6 km in 6 minutes. What is his average speed in km/h?', '["14 km/h","16 km/h","18 km/h","20 km/h"]'::jsonb, 1, '1.6 km in 6 min = 1.6 × 10 = 16 km/h.', 'easy', 1, 0.25, 0, true);
  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'Reasoning', 'Complete the series: 3, 7, 15, 31, ?', '["47","55","63","62"]'::jsonb, 2, 'Each term is double the previous plus 1: 31 × 2 + 1 = 63.', 'easy', 1, 0.25, 1, true);
  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'Odisha GK', 'Chilika Lake, where the Navy trains its sailors at INS Chilka, is in which state?', '["Andhra Pradesh","Odisha","West Bengal","Tamil Nadu"]'::jsonb, 1, 'Chilika Lake lies on Odisha''s east coast across Puri, Khordha and Ganjam districts.', 'easy', 1, 0.25, 2, true);
  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'General Science', 'Which vitamin is produced in the skin when exposed to sunlight?', '["Vitamin A","Vitamin B12","Vitamin C","Vitamin D"]'::jsonb, 3, 'Sunlight triggers Vitamin D synthesis in the skin.', 'easy', 1, 0.25, 3, true);
  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'Reasoning', 'If CAT is coded as DBU, how is DOG coded?', '["EPH","EOH","FPH","EPG"]'::jsonb, 0, 'Each letter moves one step forward: D→E, O→P, G→H.', 'medium', 1, 0.25, 4, true);
  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'General Knowledge', 'Which force guards India''s borders with Pakistan and Bangladesh?', '["CRPF","CISF","BSF","ITBP"]'::jsonb, 2, 'The Border Security Force guards the Pakistan and Bangladesh borders.', 'easy', 1, 0.25, 5, true);
  insert into public.mock_questions (type, subject, question, options, answer, explanation, difficulty, marks, negative_marks, sort_order, published)
  values ('MCQ', 'Mathematics', 'The average of 5 numbers is 24. If one number is removed the average becomes 22. The removed number is:', '["28","30","32","34"]'::jsonb, 2, 'Total 120, remaining 4 × 22 = 88, so removed = 32.', 'medium', 1, 0.25, 6, true);
