-- FAQs (only while the table is empty)
do $seed$ begin
if not exists (select 1 from public.faqs) then
  insert into public.faqs (question, answer, sort_order, published) values ('Where is Samantroy Academy?', 'Samantroy Academy is at Gosaninuagaon, Sishu Mandir Road, 300 m left of the railway station in Brahmapur (Berhampur), Ganjam, Odisha 760003. Call Debesh Samantroy on 98610 77371 or 90906 99770.', 0, true);
  insert into public.faqs (question, answer, sort_order, published) values ('Which exams does Samantroy Academy coach for?', 'Army (GD, Technical and Non-Technical), Navy SSR, MR and AA, Air Force X and Y group, SSC GD for BSF, CRPF, CISF, ITBP and SSB, Odisha Police Constable and SI, OSSC, OSSSC, OPSC and ASO, Bank PO and Clerk, Railway (RRB) and SSC CGL. Officer entries too: NDA, NA, TES, CDS, AFCAT and NCC.', 1, true);
  insert into public.faqs (question, answer, sort_order, published) values ('Can Arts and Commerce students join the Army, Navy or Air Force?', 'Yes. Arts and Commerce students are eligible for Air Force Y group, Navy MR, Army GD and SSC GD. Science students with Physics and Maths can also apply for Navy SSR, Air Force X group and Army Technical.', 2, true);
  insert into public.faqs (question, answer, sort_order, published) values ('When can I join, and when do new batches start?', 'Admissions are on. You can join after +2 (Science, Commerce or Arts) or after graduation. The next NDA batch starts on 21 September and the CDS batch on 14 October.', 3, true);
  insert into public.faqs (question, answer, sort_order, published) values ('How long has Samantroy Academy been running?', 'Since 2001. The academy marks its 25th anniversary in 2026, with 4000+ recruitments across the Army, Navy, Air Force, CAPF, Odisha Police, bank, railway and Odisha government jobs.', 4, true);
  insert into public.faqs (question, answer, sort_order, published) values ('Do you coach for officer entries like NDA, CDS and AFCAT?', 'Yes: NDA, NA, TES, CDS, AFCAT and NCC special entry. Recent officer results include AFCAT All India Rank 183 and Army ACC All India Rank 26.', 5, true);
  insert into public.faqs (question, answer, sort_order, published) values ('I live outside Brahmapur. Can I still join?', 'Yes. Our selected candidates come from across Ganjam, Gajapati, Kandhamal, Khordha, Puri, Cuttack, Nayagarh and beyond. Call the academy and we will help with accommodation near the centre.', 6, true);
  insert into public.faqs (question, answer, sort_order, published) values ('I am a few centimetres short of the height requirement. Can I still apply?', 'Possibly. Height standards differ by force, category and region, and ST candidates and some regions get relaxations. Use the Eligibility Finder or the Standards page, then talk to us so we can check the exact notification for you.', 7, true);
  insert into public.faqs (question, answer, sort_order, published) values ('Do you guarantee selection?', 'No academy can honestly guarantee selection. What we promise is regular practice against the real exam pattern and cut-offs, and honest feedback on where you stand.', 8, true);
end if;
end $seed$;
